import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { GeminiOcrInput } from '../src/tools/gemini_ocr_types.js';

describe('GeminiOcrInput zod schema', () => {
  test('accepts a minimal valid input, defaulting response_format to concise', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      target_language: 'he',
    });
    assert.equal(result.success, true);
    if (result.success) {
      assert.equal(result.data.response_format, 'concise');
      assert.equal(result.data.page_range, undefined);
    }
  });

  test('accepts a fully specified input', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      page_range: '1-20',
      target_language: 'mixed',
      response_format: 'detailed',
    });
    assert.equal(result.success, true);
  });

  test('rejects missing document_path', () => {
    const result = GeminiOcrInput.safeParse({
      target_language: 'en',
    });
    assert.equal(result.success, false);
    if (!result.success) {
      assert.ok(result.error.issues.some((i) => i.path.includes('document_path')));
    }
  });

  test('rejects empty-string document_path', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '',
      target_language: 'en',
    });
    assert.equal(result.success, false);
  });

  test('rejects bad target_language enum value', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      target_language: 'fr', // not in ["he","en","mixed"]
    });
    assert.equal(result.success, false);
    if (!result.success) {
      assert.ok(result.error.issues.some((i) => i.path.includes('target_language')));
    }
  });

  test('rejects missing target_language', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
    });
    assert.equal(result.success, false);
  });

  test('rejects invalid response_format enum value', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      target_language: 'en',
      response_format: 'verbose', // not in ["concise","detailed"]
    });
    assert.equal(result.success, false);
    if (!result.success) {
      assert.ok(result.error.issues.some((i) => i.path.includes('response_format')));
    }
  });

  test('rejects empty-string page_range (schema-level malformedness)', () => {
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      target_language: 'en',
      page_range: '',
    });
    assert.equal(result.success, false);
  });

  test('page_range full string-shape validation deferred to parsePageRange, not zod', () => {
    // zod only checks page_range is a non-empty string here; malformed page
    // tokens like "abc" are caught by parsePageRange (see batching.test.ts),
    // not by the input schema. Documented via this passing case.
    const result = GeminiOcrInput.safeParse({
      document_path: '/tmp/doc.pdf',
      target_language: 'en',
      page_range: 'abc', // zod accepts it; parsePageRange would reject it
    });
    assert.equal(result.success, true);
  });
});
